function q(s,r=document){return r.querySelector(s)}function qa(s,r=document){return [...r.querySelectorAll(s)]}
function dragOrb(){let el=q('#orb'),n=q('#nudge');if(!el)return;let p=null;try{p=JSON.parse(localStorage.getItem('ffh_ai_pos')||'null')}catch(_){}let down=false,moved=false,sx=0,sy=0,dx=0,dy=0;if(p&&Number.isFinite(+p.x)&&Number.isFinite(+p.y)){Object.assign(el.style,{left:p.x+'px',top:p.y+'px',right:'auto',bottom:'auto'});n?.classList.add('hide')}el.onpointerdown=e=>{down=true;moved=false;sx=e.clientX;sy=e.clientY;dx=e.clientX-el.offsetLeft;dy=e.clientY-el.offsetTop;try{el.setPointerCapture(e.pointerId)}catch(_){}};el.onpointermove=e=>{if(!down)return;if(Math.hypot(e.clientX-sx,e.clientY-sy)<9)return;moved=true;let x=Math.max(4,Math.min(innerWidth-el.offsetWidth-4,e.clientX-dx)),y=Math.max(68,Math.min(innerHeight-el.offsetHeight-72,e.clientY-dy));Object.assign(el.style,{left:x+'px',top:y+'px',right:'auto',bottom:'auto'});n?.classList.add('hide')};el.onpointerup=e=>{down=false;if(moved){localStorage.setItem('ffh_ai_pos',JSON.stringify({x:el.offsetLeft,y:el.offsetTop}));e.preventDefault();e.stopPropagation()}}}
