function incentive(){
 let id=currentSr()||user.id,list=db.incentives.filter(x=>x.sr===id||x.sr==='ALL'),master=catalogueProducts();
 const groups=x=>Array.isArray(x.groups)&&x.groups.length?x.groups:[{name:x.mode==='combo'?'Combo':'SKU',skus:Array.isArray(x.skus)?x.skus:(x.sku?[x.sku]:[]),target:+x.target||0,reward:+x.reward||0}];
 const groupProgress=(g)=>db.sales.filter(z=>z.sr===id&&z.status==='Delivered'&&(g.skus||[]).includes(z.sku)).reduce((a,z)=>a+(+z.qty||0),0);
 const cards=list.length?list.map(x=>`<div class="card">${x.image?`<img class="campaignImg" src="${x.image}">`:''}<div class="cardTitle">${esc(x.name)}</div>${groups(x).map(g=>{let got=groupProgress(g),tar=+g.target||0,pct=tar?Math.min(100,got/tar*100):0;return`<div class="incGroup"><b>${esc(g.name||'Incentive')}</b><div class="muted">${(g.skus||[]).map(esc).join(' + ')}</div><div class="row"><span>Progress</span><b>${got} / ${tar}</b></div><div class="progress"><span style="width:${pct}%"></span></div><div class="row"><span>Reward</span><b class="green">${rm(g.reward||0)}</b></div><div class="row"><span>Remaining</span><b class="${tar-got>0?'yellow':'green'}">${Math.max(0,tar-got)}</b></div></div>`}).join('')}</div>`).join(''):'<div class="card empty">No active product incentive published.</div>';
 const skuOptions=master.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');
 shell(back('Product Incentive')+(isMgr()?scopeBar():'')+`<div>${cards}</div>${isMgr()?`<div class="card"><div class="cardTitle">Publish Incentive Poster</div><div class="notice">SKU source = Catalogue. Catalogue-এ নতুন product add করলে এখানে automatically পাওয়া যাবে। একই poster-এর নিচে Single SKU বা Combo SKU—একাধিক incentive group add করা যাবে।</div><form class="form" id="incForm"><label>Campaign / Poster Name<input name="name" required></label><label>Assign To<select name="sr"><option>ALL</option>${srIds().map(x=>`<option value="${x}">${sr(x).name}</option>`).join('')}</select></label><label>One Poster / Artwork<input name="image" type="file" accept="image/*"></label><div id="incGroups"></div><button type="button" class="secondary" id="addIncGroup">+ ADD SINGLE / COMBO INCENTIVE</button><button class="primary premiumBtn">PUBLISH INCENTIVE</button></form></div>`:''}`);
 bindBack();bindScope(incentive);
 if(q('#incForm')){let n=0,box=q('#incGroups');const addGroup=()=>{let i=n++,d=document.createElement('div');d.className='card incBuilder';d.dataset.i=i;d.innerHTML=`<div class="row"><b>Incentive Group ${i+1}</b><button type="button" class="danger removeIncGroup">REMOVE</button></div><label>Group / Combo Name<input class="gName" placeholder="e.g. Mango Juice / Basil Seed Combo" required></label><label>Type<select class="gMode"><option value="single">Single SKU</option><option value="combo">Combo SKU</option></select></label><label>Catalogue SKU(s)<select class="gSkus" multiple size="7" required>${skuOptions}</select></label><div class="two"><label>Target Carton<input class="gTarget" type="number" min="0" step=".01" required></label><label>Reward RM<input class="gReward" type="number" min="0" step=".01" required></label></div>`;box.appendChild(d);d.querySelector('.removeIncGroup').onclick=()=>{if(box.children.length>1)d.remove()}};addGroup();q('#addIncGroup').onclick=addGroup;
 q('#incForm').onsubmit=async e=>{e.preventDefault();let fd=new FormData(e.target),groupsOut=[];for(let d of [...box.children]){let mode=d.querySelector('.gMode').value,skus=[...d.querySelector('.gSkus').selectedOptions].map(o=>o.value);if(mode==='single'&&skus.length!==1)return alert('Single SKU group-এ ঠিক ১টি Catalogue SKU select করুন।');if(mode==='combo'&&skus.length<2)return alert('Combo group-এ কমপক্ষে ২টি Catalogue SKU select করুন।');groupsOut.push({name:d.querySelector('.gName').value.trim(),mode,skus,target:+d.querySelector('.gTarget').value||0,reward:+d.querySelector('.gReward').value||0})}let f=fd.get('image'),image='';try{image=f?.size?await fileData(f):''}catch(err){return alert(err.message)}db.incentives.push({id:'I'+Date.now(),name:fd.get('name'),sr:fd.get('sr'),image,groups:groupsOut,date:today()});save();incentive()}}
}
function cpo(){
 shell(back('CPO / Promotion')+`<section class="ffPremiumHub"><div class="ffPremiumTitle"><div><h1>CPO <span>/</span> Promotion</h1><p>EXECUTE · ENGAGE · GROW</p></div><em>Same Team<br>Bigger Results!</em></div><button class="ffCoverBtn cpoHubBtn" data-type="CPO"><img src="ffh-cpo-cover.png" alt="CPO Campaign Execution"></button><button class="ffCoverBtn ffPromo cpoHubBtn" data-type="Promotion"><img src="ffh-promotion-cover.png" alt="Promotion Sales Activation"></button><div class="ffWeapons"><strong>Your<br><span>Sales Weapons.</span></strong><small>PLAN SMART · EXECUTE BETTER · ACHIEVE BIGGER</small><b>Discipline<br>Creates Freedom!</b></div><div class="ffBottomQuote ffMotivationFooter"><span>“ Same Team · Bigger Tomorrow ”</span></div></section>`);
 bindBack();
 qa('.cpoHubBtn').forEach(b=>b.onclick=async()=>{
   let type=b.dataset.type;
   b.disabled=true;
   try{
     let localBefore=(db.cpoCampaigns||[]).slice();
     let loaded=await ffhLoadCpoShared();
     // Safe manager self-heal: if cloud has no campaign but this manager device has existing campaigns,
     // publish those existing campaigns once instead of showing an empty SR screen.
     if(isMgr() && (!loaded || !(db.cpoCampaigns||[]).length) && localBefore.length){
       db.cpoCampaigns=localBefore; save();
       await ffhSaveCpoShared();
     }
   }catch(e){console.warn('CPO refresh failed',e)}
   finally{b.disabled=false}
   cpoTypePage(type,month());
 })
}
function cpoMonthLabel(m){let [y,mo]=String(m||month()).split('-').map(Number);return new Date(y,mo-1,1).toLocaleDateString(lang==='bn'?'bn-BD':'en-US',{month:'long',year:'numeric'})}
function cpoCampaignMonths(c){let a=String(c.startDate||c.date||today()).slice(0,7),b=String(c.endDate||c.startDate||c.date||today()).slice(0,7);return[a,b]}
function cpoCampaignHeading(c){let [a,b]=cpoCampaignMonths(c),la=cpoMonthLabel(a),lb=cpoMonthLabel(b);return `${c.type||'CPO'} for ${la}${a!==b?' to '+lb:''}`}
function cpoTypePage(type,selectedMonth=month()){
 let id=currentSr(),ids=id?[id]:srIds(),want=String(type||'CPO').trim().toLowerCase(),campaigns=(db.cpoCampaigns||[]).filter(c=>{let ct=String(c.type||'CPO').trim().toLowerCase(),as=String(c.sr||'ALL').trim();return c.active!==false&&ct===want&&(as.toUpperCase()==='ALL'||ids.includes(as))}).filter(c=>{let[a,b]=cpoCampaignMonths(c);return selectedMonth>=a&&selectedMonth<=b});
 shell(back(type)+`<section class="ffCampaignPage ${type==='Promotion'?'ffPromotionPage':''}"><div class="ffCampaignTop"><div><h1>${esc(type)} <span>Campaigns</span></h1><p>Month-wise archive & execution</p></div><em>${type==='CPO'?'Execute · Display · Grow!':'More Visibility · More Sales!'}</em></div><div class="ffMonthBar"><b>▣ &nbsp; Select Month</b><input id="cpoMonthPick" type="month" value="${esc(selectedMonth)}"></div><div class="ffCampaignHeading"><div><h2>${esc(type)} for ${esc(cpoMonthLabel(selectedMonth))}</h2><small>${campaigns.length} campaign${campaigns.length===1?'':'s'}</small></div>${isMgr()?`<button class="primary ffAddCampaign" id="ffAddCampaign">＋ Add Campaign</button>`:''}</div>${campaigns.length?`<div class="ffCampaignList">${campaigns.map(c=>cpoCampaignCard(c,ids)).join('')}</div>`:`<div class="card empty">No ${esc(type)} campaign for this month.<br><button class="secondary" id="cpoReloadCloud" style="margin-top:10px">RELOAD CLOUD CAMPAIGNS</button></div>`}${isMgr()?`<button class="primary" id="cpoExcel">DOWNLOAD CPO/PROMOTION EXCEL</button>`:''}<div class="ffBottomQuote">“ ${type==='CPO'?'On Ground · On Shelf · On Growth!':'Plan · Execute · Grow!'} ”</div></section>`);
 q('#back').onclick=()=>cpo();q('#cpoMonthPick').onchange=e=>cpoTypePage(type,e.target.value);
 if(q('#ffAddCampaign'))q('#ffAddCampaign').onclick=()=>{let o=document.createElement('div');o.className='globalSearchOverlay';o.innerHTML=`<div class="globalSearchBox ffPremiumModal">${cpoManagerForm(type,selectedMonth)}</div>`;document.body.appendChild(o);o.querySelector('.ffModalBack').onclick=()=>o.remove();o.onclick=e=>{if(e.target===o)o.remove()};bindCpoCampaignActions(type,selectedMonth,o)};
 bindCpoCampaignActions(type,selectedMonth);if(q('#cpoReloadCloud'))q('#cpoReloadCloud').onclick=async()=>{try{await ffhLoadCpoShared();cpoTypePage(type,selectedMonth)}catch(e){alert('CPO cloud reload failed: '+(e?.message||e))}};if(q('#cpoExcel'))q('#cpoExcel').onclick=exportCpoExcel
}
function cpoCampaignCard(c,ids){
 let exec=(db.cpo||[]).filter(x=>x.campaignId===c.id&&ids.includes(x.sr)),proof=c.executionMode!=='view',assigned=[];ids.filter(sid=>c.sr==='ALL'||c.sr===sid).forEach(sid=>outlets(sid).filter(o=>!c.category||c.category==='ALL'||o.category===c.category).forEach(o=>assigned.push({sid,o})));let done=new Set(exec.filter(x=>/DONE|SUBMITTED|VERIFIED/i.test(x.status||'')).map(x=>x.sr+'|'+x.outletCode));
 return `<article class="cpoCampaign ffReferenceCampaign ${c.type==='Promotion'?'ffRefPromotion':''}">${isMgr()?`<button class="cpoDots" data-id="${c.id}">⋮</button>`:''}<span class="ffCampaignNo">#</span><div class="ffCampaignPoster">${c.image?`<img class="campaignImg zoomable" src="${c.image}">`:`<div class="ffPosterEmpty">UPLOAD POSTER</div>`}</div><div class="ffCampaignInfo"><div><div class="cardTitle">${esc(c.title)}</div><div class="muted">${esc(cpoCampaignHeading(c))} · ${proof?'PHOTO PROOF':'VIEW ONLY'} · ${esc(c.category||'ALL')}</div></div>${isMgr()?`<span class="ffActiveBadge">● ACTIVE</span>`:''}</div>${!isMgr()?(proof?`<div class="notice">Assigned outlet অনুযায়ী photo upload না করা পর্যন্ত PENDING থাকবে।</div><div class="miniStat">Pending: ${assigned.filter(a=>a.sid===user.id&&!done.has(a.sid+'|'+a.o.code)).length}</div><form class="form cpoExec" data-cid="${c.id}"><label>Outlet<select name="outlet" required><option value="">Select outlet</option>${assigned.filter(a=>a.sid===user.id).map(a=>`<option value="${esc(a.o.code)}">${esc(a.o.name)} · ${done.has(a.sid+'|'+a.o.code)?'DONE':'PENDING'}</option>`).join('')}</select></label><label>Execution Photo<input name="photo" type="file" accept="image/*" capture="environment" required></label><label>Remarks<textarea name="remarks"></textarea></label><button class="primary">UPLOAD EXECUTION</button></form>`:`<div class="notice green">View-only campaign — poster দেখার জন্য; photo upload required নয়।</div>`):`<div class="ffCampaignStats"><span><b>${assigned.length}</b><small>Assigned</small></span><span class="done"><b>${done.size}</b><small>Done</small></span><span class="pending"><b>${Math.max(0,assigned.length-done.size)}</b><small>Pending</small></span></div>`}</article>`
}
function cpoManagerForm(type,m){return `<div class="card"><button type="button" class="ffModalBack">← Back</button><div class="cardTitle">Publish ${esc(type)}</div><form class="form" id="campaignForm"><input type="hidden" name="type" value="${esc(type)}"><label>Campaign Title<input name="title" required></label><div class="two"><label>Start Date<input name="startDate" type="date" value="${m}-01" required></label><label>End Date<input name="endDate" type="date" value="${m}-28" required></label></div><label>Execution Requirement<select name="executionMode"><option value="proof">Photo Proof Required</option><option value="view">View Only — No Upload</option></select></label><label>Assign To<select name="sr"><option>ALL</option>${srIds().map(x=>`<option value="${x}">${sr(x).name}</option>`).join('')}</select></label><label>Outlet Category<input name="category" value="ALL"></label><label>Product / SKU<input name="product" placeholder="Optional"></label><label>${esc(type)} Cover / Poster<input name="image" type="file" accept="image/*" required></label><button class="primary">PUBLISH ${esc(type).toUpperCase()}</button></form></div>`}
function bindCpoCampaignActions(type,m){
 if(q('#campaignForm'))q('#campaignForm').onsubmit=async e=>{e.preventDefault();let fd=new FormData(e.target),f=fd.get('image');try{let image=await fileData(f,1800000);if(/^data:/i.test(String(image||'')))image=await ffhDataUrlUpload(image,'ffh-public','campaigns/'+ffhSafeName(fd.get('type')||'CPO')+'/campaign-'+Date.now());db.cpoCampaigns.push({id:'CP'+Date.now(),title:fd.get('title'),type:fd.get('type'),startDate:fd.get('startDate'),endDate:fd.get('endDate'),executionMode:fd.get('executionMode')||'proof',sr:fd.get('sr'),category:fd.get('category')||'ALL',product:fd.get('product')||'',image,active:true,date:today()});save();await ffhSaveCpoShared();cpoTypePage(type,m)}catch(err){alert(err.message)}};
 qa('.cpoExec').forEach(form=>form.onsubmit=async e=>{e.preventDefault();let fd=new FormData(form),code=fd.get('outlet'),o=outlets(user.id).find(x=>x.code===code),f=fd.get('photo');if(!f?.size)return alert('Execution photo required.');let photo='';try{photo=await fileData(f,1600000)}catch(err){return alert(err.message)}let old=db.cpo.find(x=>x.campaignId===form.dataset.cid&&x.sr===user.id&&x.outletCode===code),obj={id:old?.id||'CX'+Date.now(),campaignId:form.dataset.cid,sr:user.id,outlet:o?.name||code,outletCode:code,category:o?.category||'',photo,remarks:fd.get('remarks'),date:today(),status:'DONE'};if(old)Object.assign(old,obj);else db.cpo.push(obj);save();cpoTypePage(type,m)});
 qa('.cpoDots').forEach(b=>b.onclick=()=>openCpoMenu(b.dataset.id,type,m));bindCatalogueZoom()
}
function openCpoMenu(id,type,m){let c=db.cpoCampaigns.find(x=>x.id===id);if(!c)return;let o=document.createElement('div');o.className='globalSearchOverlay';o.innerHTML=`<div class="globalSearchBox" style="max-width:360px"><div class="cardTitle">${esc(c.title)}</div><button class="primary cpoEdit" style="width:100%;margin:10px 0">EDIT CAMPAIGN</button><button class="danger cpoDelete" style="width:100%;margin:10px 0">DELETE CAMPAIGN</button><button class="secondary cpoCancel" style="width:100%">CANCEL</button></div>`;document.body.appendChild(o);o.querySelector('.cpoCancel').onclick=()=>o.remove();o.querySelector('.cpoEdit').onclick=()=>{o.remove();editCpoCampaign(id,type,m)};o.querySelector('.cpoDelete').onclick=()=>{if(!confirm('Delete this campaign?\n\nExecution history for this campaign will also be removed.'))return;db.cpoCampaigns=db.cpoCampaigns.filter(x=>x.id!==id);db.cpo=db.cpo.filter(x=>x.campaignId!==id);save();ffhSaveCpoShared().catch(e=>console.warn(e));o.remove();cpoTypePage(type,m)}}
function editCpoCampaign(id,type,m){let c=db.cpoCampaigns.find(x=>x.id===id);if(!c)return;let o=document.createElement('div');o.className='globalSearchOverlay';o.innerHTML=`<div class="globalSearchBox" style="max-width:440px;max-height:90vh;overflow:auto"><div class="cardTitle">Edit ${esc(type)}</div><form class="form" id="editCpoForm"><label>Campaign Title<input name="title" value="${esc(c.title)}" required></label><div class="two"><label>Start Date<input name="startDate" type="date" value="${esc(c.startDate||c.date||today())}" required></label><label>End Date<input name="endDate" type="date" value="${esc(c.endDate||c.startDate||c.date||today())}" required></label></div><label>Execution Requirement<select name="executionMode"><option value="proof" ${c.executionMode!=='view'?'selected':''}>Photo Proof Required</option><option value="view" ${c.executionMode==='view'?'selected':''}>View Only — No Upload</option></select></label><label>Assign To<select name="sr"><option ${c.sr==='ALL'?'selected':''}>ALL</option>${srIds().map(x=>`<option value="${x}" ${c.sr===x?'selected':''}>${sr(x).name}</option>`).join('')}</select></label><label>Outlet Category<input name="category" value="${esc(c.category||'ALL')}"></label><label>Product / SKU<input name="product" value="${esc(c.product||'')}"></label><label>Replace Cover / Poster<input name="image" type="file" accept="image/*"></label><button class="primary">SAVE CHANGES</button><button type="button" class="secondary cpoCancel">CANCEL</button></form></div>`;document.body.appendChild(o);o.querySelector('.cpoCancel').onclick=()=>o.remove();o.querySelector('#editCpoForm').onsubmit=async e=>{e.preventDefault();let fd=new FormData(e.target),f=fd.get('image'),image='';try{if(f?.size){image=await fileData(f,1800000);if(/^data:/i.test(String(image||'')))image=await ffhDataUrlUpload(image,'ffh-public','campaigns/'+ffhSafeName(type)+'/campaign-'+Date.now())}}catch(err){return alert(err.message)}c.title=fd.get('title');c.startDate=fd.get('startDate');c.endDate=fd.get('endDate');c.executionMode=fd.get('executionMode');c.sr=fd.get('sr');c.category=fd.get('category')||'ALL';c.product=fd.get('product')||'';if(image)c.image=image;save();await ffhSaveCpoShared();o.remove();cpoTypePage(type,String(c.startDate).slice(0,7)||m)}}
async function exportCpoExcel(){
 try{const XLSX=await ffhEnsureXlsx();const id=currentSr(),allowed=id?[id]:srIds();const rows=[['Campaign','Type','SR','Outlet','Category','Date','Status','Remarks','Photo URL'],...(db.cpo||[]).filter(x=>allowed.includes(x.sr)).map(x=>{const c=(db.cpoCampaigns||[]).find(z=>z.id===x.campaignId)||{};return[c.title||'',c.type||x.type||'',sr(x.sr)?.name||x.sr,x.outlet||'',x.category||'',x.date||'',x.status||'',x.remarks||'',/^https?:/i.test(x.photo||'')?x.photo:'']})];const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(rows),'CPO Promotion');ffhSafeDownload(new Blob([XLSX.write(wb,{bookType:'xlsx',type:'array'})],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),'CPO-Promotion-'+today()+'.xlsx')}
 catch(e){console.error(e);alert('CPO Excel download failed: '+(e.message||e))}
}
function zero(){let id=currentSr(),zs=zeroOutlets(id);shell(back('Zero Sales')+(isMgr()?scopeBar():'')+`<div class="highlightStrip"><div class="alertBox"><span class="muted">ZERO OUTLETS</span><b class="red">${zs.length}</b></div><div class="alertBox yellow"><span class="muted">ASSIGNED TOTAL</span><b>${id?outlets(id).length:srIds().reduce((a,x)=>a+outlets(x).length,0)}</b></div></div><div class="card"><div class="cardTitle">${id?'Individual Zero-Sales Outlets':'All SR — Combined Zero-Sales Outlets'}</div>${zs.length?zs.map(o=>`<div class="row"><div><b>${o.name}</b><div class="miniStat">${o.code} · ${o.category}${isMgr()?' · '+short(sr(o.sr)?.name):''}</div></div><span class="zeroBadge">ZERO</span></div>`).join(''):'<div class="empty green">All assigned outlets covered.</div>'}</div>`);bindBack();bindScope(zero)}function route(){let id=currentSr(),ids=id?[id]:srIds(),rows=[];ids.forEach(sid=>outlets(sid).forEach(o=>rows.push({...o,sr:sid,srName:sr(sid)?.name||sid})));let salesBy={};db.sales.filter(x=>ids.includes(x.sr)&&x.status==='Delivered'&&String(x.date||'').startsWith(month())&&(+x.deliveredAmount>0||+x.qty>0)).forEach(x=>salesBy[x.sr+'|'+(x.outletCode||x.outletName)]=(salesBy[x.sr+'|'+(x.outletCode||x.outletName)]||0)+(+x.deliveredAmount||0));let sorted=rows.slice().sort((a,b)=>(salesBy[a.sr+'|'+a.code]||0)-(salesBy[b.sr+'|'+b.code]||0));shell(back('Route & Zero-Sales Focus')+(isMgr()?scopeBar():'')+`<div class="kpis"><div class="kpi"><span>Assigned Outlets</span><strong>${rows.length}</strong></div><div class="kpi"><span>Zero Sales</span><strong class="red">${zeroCount(id)}</strong></div></div><div class="card"><div class="cardTitle">${id?'Individual Outlet Status':'All SR — Combined Outlet Status'}</div>${sorted.length?sorted.map(o=>{let k=o.sr+'|'+o.code,v=salesBy[k]||0;return`<div class="row"><div><b>${o.name}</b><div class="miniStat">${o.code} · ${o.category}${isMgr()?' · '+short(o.srName):''}</div></div><span class="${v?'green':'zeroBadge'}">${v?rm(v):'ZERO'}</span></div>`}).join(''):'<div class="empty">No outlet assigned.</div>'}</div>`);bindBack();bindScope(route)}function tasks(){let id=currentSr()||user.id,scopeIds=isMgr()&&view==='ALL'?['ALL',...srIds(),'M21954']:[id,'ALL'],list=db.tasks.filter(x=>scopeIds.includes(x.to)&&String(x.created||today()).startsWith(month())).sort((a,b)=>(a.status==='Done')-(b.status==='Done')||String(a.due||'9999').localeCompare(String(b.due||'9999'))),notes=db.notes.filter(x=>x.owner===user.id);let assignOptions=isMgr()?`<option value="ALL">ALL SR</option>${srIds().map(x=>`<option value="${x}">${sr(x).name}</option>`).join('')}`:`<option value="M21954">Manager</option>`;shell(back('Tasks, Notes & Reminders')+(isMgr()?scopeBar():'')+`<div class="card"><div class="cardTitle">This Month — Pending First</div>${list.length?list.map(x=>`<div class="taskRow ${x.status==='Done'?'doneTask':''}"><div><b>${esc(x.title)}</b><div class="miniStat">To: ${x.to==='ALL'?'ALL SR':short(sr(x.to)?.name||'Manager')} · Given by: ${esc(x.by||'—')} · ${x.due||'No due date'}</div></div><button class="${x.status==='Done'?'success':'secondary'} taskDone" data-id="${x.id}">${x.status==='Done'?'DONE':'MARK DONE'}</button></div>`).join(''):'<div class="empty">No task this month.</div>'}</div><div class="card"><form class="form" id="taskForm"><label>Task<input name="title" required></label><label>Assign To<select name="to">${assignOptions}</select></label><label>Due<input name="due" type="date"></label><label>Priority<select name="priority"><option>Normal</option><option>High</option><option>Urgent</option></select></label><button class="primary">ASSIGN TASK</button></form></div><div class="card"><div class="cardTitle">My Private Notepad</div><form class="form" id="noteForm"><label>Note<textarea name="text" required></textarea></label><label>Reminder Date & Time<input name="remind" type="datetime-local"></label><button class="primary">SAVE NOTE / REMINDER</button></form>${notes.slice().reverse().map(n=>`<div class="row"><div><b>${esc(n.text)}</b><div class="miniStat">${n.remind||'No reminder'}</div></div><button class="danger delNote" data-id="${n.id}">DELETE</button></div>`).join('')}</div>`);bindBack();bindScope(tasks);q('#taskForm').onsubmit=e=>{e.preventDefault();db.tasks.push({...Object.fromEntries(new FormData(e.target)),id:'T'+Date.now(),by:user.name,byId:user.id,created:today(),status:'Open'});save();tasks()};qa('.taskDone').forEach(b=>b.onclick=()=>{let x=db.tasks.find(t=>t.id===b.dataset.id);if(x){x.status=x.status==='Done'?'Open':'Done';x.doneAt=x.status==='Done'?new Date().toISOString():'';save();tasks()}});q('#noteForm').onsubmit=e=>{e.preventDefault();let n=Object.fromEntries(new FormData(e.target));db.notes.push({...n,id:'N'+Date.now(),owner:user.id});save();scheduleNoteReminder(n);tasks()};qa('.delNote').forEach(b=>b.onclick=()=>{db.notes=db.notes.filter(n=>n.id!==b.dataset.id);save();tasks()})}
function scheduleNoteReminder(n){if(!n.remind)return;let ms=new Date(n.remind)-new Date();if(ms>0&&ms<2147483647)setTimeout(()=>notifyNow('FieldForce Reminder',n.text),ms)}
function ffhRawFileData(file,max=6000000){return new Promise((res,rej)=>{if(!file)return res('');if(file.size>max)return rej(new Error('File too large. Keep under '+Math.round(max/1000000*10)/10+' MB.'));let r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file)})}
function ffhSafeName(s='file'){return String(s).toLowerCase().replace(/[^a-z0-9._-]+/g,'-').replace(/^-+|-+$/g,'').slice(0,80)||'file'}
async function ffhUploadPublicFile(file,folder){if(!file?.size)throw new Error('Please choose a file.');let ext=(file.name.split('.').pop()||'bin').toLowerCase(),path=`${folder}/${Date.now()}-${Math.random().toString(36).slice(2,8)}-${ffhSafeName(file.name.replace(/\.[^.]+$/,''))}.${ext}`;let {error}=await FFH_SUPABASE.storage.from('ffh-public').upload(path,file,{contentType:file.type||'application/octet-stream',upsert:false});if(error)throw error;let {data}=FFH_SUPABASE.storage.from('ffh-public').getPublicUrl(path);return data.publicUrl}
