 qa('.zoomable').forEach(im=>im.onclick=()=>{let o=document.createElement('div');o.className='imageLightbox';o.innerHTML=`<button class="ffLightboxBack">← Back</button><img src="${im.src}">`;document.body.appendChild(o);o.querySelector('.ffLightboxBack').onclick=()=>o.remove();o.onclick=e=>{if(e.target===o)o.remove()}});
