async function ffhFindCatalogueCloud(x){
 if(!window.FFH_SUPABASE)return null;
 let q=FFH_SUPABASE.from('ffh_catalogue_products').select('id,item_code,name,category,image_url,serial_no,active');
 if(x?.cloudId){let r=await q.eq('id',x.cloudId).maybeSingle();if(r.error)throw r.error;if(r.data)return r.data}
 if(x?.id){let r=await FFH_SUPABASE.from('ffh_catalogue_products').select('id,item_code,name,category,image_url,serial_no,active').eq('id',String(x.id)).maybeSingle();if(r.error)throw r.error;if(r.data)return r.data}
 if(x?.itemCode){let r=await FFH_SUPABASE.from('ffh_catalogue_products').select('id,item_code,name,category,image_url,serial_no,active').eq('item_code',String(x.itemCode)).eq('name',x.name).maybeSingle();if(r.error)throw r.error;if(r.data)return r.data}

 return null;
}
async function ffhAssertManagerCloudWrite(){
 if(!window.FFH_SUPABASE)throw new Error('Cloud unavailable. Reconnect and retry.');
 const {data:sessionResult,error:sessionError}=await FFH_SUPABASE.auth.getSession();
 if(sessionError||!sessionResult?.session?.user)throw new Error('Manager cloud session expired. Sign out and log in as Manager again.');
 const {data:profile,error:profileError}=await FFH_SUPABASE.from('ffh_profiles').select('staff_id,active,can_manage,auth_user_id').eq('auth_user_id',sessionResult.session.user.id).maybeSingle();
 if(profileError)throw new Error('Cannot verify Manager permissions: '+profileError.message);
 if(!profile?.active||!profile?.can_manage||String(profile.staff_id).toUpperCase()!=='M21954')throw new Error('This cloud session has no Manager write permission. Sign out and log in using the Manager account. No changes have been published.');
 return profile;
}
async function ffhSaveCatalogueCloud(x){
 if(!window.FFH_SUPABASE||!x)return null;
 await ffhAssertManagerCloudWrite();
 let existing=await ffhFindCatalogueCloud(x);
 let payload={item_code:String(x.itemCode||''),name:x.name||'',category:x.category||'Other Products',carton_qty:Number(x.ctnFactors||x.cartonQty)||0,piece_price:+x.piecePrice||0,carton_price:+x.cartonPrice||0,image_url:x.image||x.image_url||'',serial_no:+x.serialNo||0,pack:x.pack||'',ctn_factors:String(x.ctnFactors||''),ctn_barcode:x.ctnBarcode||'',combo_barcode:x.comboBarcode||'',single_pcs_barcode:x.singlePcsBarcode||'',comparison:x.comparison||'',comparison_bn:x.comparisonBn||'',description:x.description||'',origin:x.origin||'',process:x.process||'',talking_points:x.talkingPoints||'',pitch:x.pitch||'',description_bn:x.descriptionBn||'',origin_bn:x.originBn||'',process_bn:x.processBn||'',talking_points_bn:x.talkingPointsBn||'',pitch_bn:x.pitchBn||'',buyer_sections:x.buyerSections||{},active:x.active!==false};
 let r=existing?.id
   ? await FFH_SUPABASE.from('ffh_catalogue_products').update(payload).eq('id',existing.id).select('id').single()
   : await FFH_SUPABASE.from('ffh_catalogue_products').insert({...payload,id:(x.cloudId||x.id||('ffh-'+(typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+'-'+Math.random().toString(36).slice(2))))}).select('id').single();
 if(r.error){if(/row.level security|row-level security|permission denied/i.test(r.error.message||''))throw new Error('Cloud rejected this write under RLS. Confirm your Manager account is signed in to Supabase, then retry. '+r.error.message);throw r.error;}
 x.cloudId=r.data?.id||existing?.id||x.cloudId||'';
 return r.data;
}
async function ffhDeleteCatalogueCloud(x){
 if(!window.FFH_SUPABASE||!x)return;
 let existing=await ffhFindCatalogueCloud(x);
 if(existing?.id){let {error}=await FFH_SUPABASE.from('ffh_catalogue_products').update({active:false}).eq('id',existing.id);if(error)throw error}
 else {let payload={item_code:String(x.itemCode||''),name:x.name||'',category:x.category||'Other Products',image_url:x.image||'',serial_no:+x.serialNo||0,active:false};let {error}=await FFH_SUPABASE.from('ffh_catalogue_products').insert({...payload,id:(x.cloudId||x.id||('ffh-'+(typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+'-'+Math.random().toString(36).slice(2))))});if(error)throw error}
}
async function ffhSyncCategorySerialCloud(category){
 if(!window.FFH_SUPABASE)return;
 let rows=ffhCatalogueRows().filter(x=>x.category===category).sort((a,b)=>(a.serialNo||999999)-(b.serialNo||999999));
 let codes=rows.map(x=>String(x.itemCode||''));if(codes.every(Boolean)&&new Set(codes).size===codes.length){let {data,error}=await FFH_SUPABASE.rpc('ffh_reorder_catalogue',{p_item_codes:codes,p_category:category});if(!error&&data===rows.length)return;if(error)console.warn('Atomic reorder fallback:',error.message)}for(let x of rows){await ffhSaveCatalogueCloud(x)}
}

async function ffhDataUrlUpload(dataUrl,bucket,path){
 if(!/^data:/i.test(String(dataUrl||'')))return dataUrl;
 let m=String(dataUrl).match(/^data:([^;]+);base64,(.+)$/);if(!m)return dataUrl;
 let mime=m[1],bin=atob(m[2]),bytes=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);
 let ext=(mime.split('/')[1]||'jpg').replace('jpeg','jpg').replace(/[^a-z0-9]/gi,'')||'jpg';let full=path+'.'+ext;
 let {error}=await FFH_SUPABASE.storage.from(bucket).upload(full,bytes,{contentType:mime,upsert:true});if(error)throw error;
 if(bucket==='ffh-public'||bucket==='ffh-migration'){let {data}=FFH_SUPABASE.storage.from(bucket).getPublicUrl(full);return data.publicUrl}
 return full;
}
async function ffhCloudifyLocalData(source,onProgress){
 let out=JSON.parse(JSON.stringify(source||{})),jobs=[];
 const add=(obj,key,bucket,path)=>{if(obj&&/^data:/i.test(String(obj[key]||'')))jobs.push({obj,key,bucket,path})};
 let stamp='migration/'+(user?.id||'manager')+'/'+Date.now();
 (out.users||[]).forEach((x,i)=>add(x,'photo','ffh-migration',stamp+'/profiles/'+(x.id||i)));
 (out.catalogue||[]).forEach((x,i)=>add(x,'image','ffh-migration',stamp+'/catalogue/product-'+i));
 Object.entries(out.catalogueCategories||{}).forEach(([k,x],i)=>{if(typeof x==='object')add(x,'cover','ffh-migration',stamp+'/catalogue/category-'+i)});
 (out.cpoCampaigns||[]).forEach((x,i)=>add(x,'image','ffh-migration',stamp+'/campaigns/campaign-'+i));
 (out.incentives||[]).forEach((x,i)=>add(x,'image','ffh-migration',stamp+'/incentives/incentive-'+i));
 (out.cpo||[]).forEach((x,i)=>{add(x,'photo','ffh-migration','proofs/'+(x.sr||user?.id||'unknown')+'/migration/proof-'+i);add(x,'image','ffh-migration','proofs/'+(x.sr||user?.id||'unknown')+'/migration/proof-'+i)});
 for(let i=0;i<jobs.length;i++){let j=jobs[i];onProgress?.('Uploading images '+(i+1)+' / '+jobs.length+'…');j.obj[j.key]=await ffhDataUrlUpload(j.obj[j.key],j.bucket,j.path)}
 return out;
}
async function ffhInsertIfEmpty(table,rows,onProgress){
 rows=(rows||[]).filter(Boolean);if(!rows.length)return{table,status:'EMPTY',local:0,cloud:0};
 let {count,error:ce}=await FFH_SUPABASE.from(table).select('*',{count:'exact',head:true});if(ce)throw ce;
 if((count||0)>0)return{table,status:'SKIPPED_EXISTING',local:rows.length,cloud:count||0};
 onProgress?.('Writing '+table+'…');let {error}=await FFH_SUPABASE.from(table).insert(rows);if(error)throw error;
 let {count:after,error:ae}=await FFH_SUPABASE.from(table).select('*',{count:'exact',head:true});if(ae)throw ae;
 return{table,status:after===rows.length?'PASS':'CHECK',local:rows.length,cloud:after||0};
}
