function aiAnswer(s){let z=s.toLowerCase(),id=currentSr()||'M21954',d=delivered(id),t=target(id),sh=Math.max(0,t-d);if(/তৈরি|creator|created|বানাই|কে বানিয়েছে|কে বানিয়েছে|who made you|who created you/.test(z)){let k=db.kb||{};return lang==='bn'?`স্যার 😄 আমাকে তৈরি ও পরিকল্পনা করেছেন ${k.creator||'Mehedi Alim Ayon'} — ${k.designation||'Key Account Manager'}, ${k.company||'Pinnacle Foods (M) Sdn. Bhd.'}। উনি আমাকে বানিয়েছেন যেন Sales-এর হিসাব, outlet, target, route আর execution নিয়ে টিমকে বারবার ক্যালকুলেটর হাতে দৌড়াতে না হয় 😄। আমি AYON AI—FieldForce Hub-এর Sales Assistant; available data থাকলে খুঁজে দেব, না থাকলে বানিয়ে বলব না।`:`Sir 😄 I was created and planned by ${k.creator||'Mehedi Alim Ayon'} — ${k.designation||'Key Account Manager'}, ${k.company||'Pinnacle Foods (M) Sdn. Bhd.'}. He built me to make sales, outlet, target, route and execution support faster—with a little humour so the team does not get bored 😄. I am AYON AI, the FieldForce Hub Sales Assistant; if the data exists I will find it, and if it does not, I will not invent it.`}if(/head of sales|হেড অফ সেলস|পারভেজ|parvez/.test(z)){let k=db.kb||{},n=k.headOfSales||'Md Parvez Hira',scope=k.headOfSalesScope||'Modern Trade';return lang==='bn'?`স্যার, ${scope}-এর Head of Sales হলেন ${n} স্যার। তিনি sales leadership, team direction, target execution, market development এবং প্রয়োজনীয় escalation-এ নেতৃত্ব দেন।`:`Sir, ${n} is Head of Sales for ${scope}. He leads sales direction, team execution, target delivery, market development and required escalations.`}if(/chairman|ceo|চেয়ারম্যান|সিইও|md|ম্যানেজিং ডিরেক্টর|মালিক|owner/.test(z)){return 'স্যার, এই তথ্যটি Manager-এর existing AI Knowledge Base-এ Q&A হিসেবে save করা থাকলে আমি সেটাই বলব। Saved Q&A না থাকলে আমি নাম বানিয়ে বলব না।';}if(/cpo|dpo|promotion|প্রমোশন/.test(z)){let rows=db.cpo.filter(x=>x.sr===id||(!currentSr()&&isMgr()));if(!rows.length)return 'স্যার, available data-তে এই scope-এর কোনো CPO/Promotion execution record পাইনি।';let done=rows.filter(x=>/verified|done|submitted/i.test(x.status||'')).length;return `স্যার, ${rows.length}টি CPO/Promotion execution record পেয়েছি; ${done}টি submitted/verified/done status-এ আছে।`;}if(/গালি|বোকা|idiot|stupid|fuck|শালা|হারামি/.test(z))return 'স্যার 😄 ব্যক্তিগত কথায় না যাই—Sales battlefield-এ ফিরি। Outlet, buyer, target, route বা execution নিয়ে বলুন; আমি সেখানেই আপনার wingman।';if(/অর্ডার.*দিচ্ছে না|order.*not|order.*দিতে.*চাচ্ছে না/.test(z))return 'স্যার, buyer একটু কঠিন হলেই হাপিয়ে গেলে চলবে? 😄 আগে stock, return, shelf, price tag আর slow SKU—এই পাঁচটা check করুন। Relationship warm রাখুন; সুযোগ থাকলে PRAN juice/Power দিয়ে আলাপটা friendly করুন। তারপরও stuck হলে Key Account Manager-এর সাথে কথা বলুন; escalation লাগলে Head of Sales Md Parvez Hira স্যার আছেন।';if(isMgr()){let hit=U.find(u=>z.includes((u.name||'').toLowerCase().split(' ').slice(-1)[0])||z.includes(u.id.toLowerCase()));if(hit){id=hit.id;d=delivered(id);t=target(id);sh=Math.max(0,t-d)}}if(/short|শর্ট|বাকি/.test(z))return `স্যার, target ${rm(t)}, delivered ${rm(d)}—বর্তমান shortfall ${rm(sh)}। ${sh?'Gap আছে, কিন্তু panic না—delivery confirmation ঠিক রাখলে picture পরিষ্কার থাকবে 😄':'Target complete, এখন over-achievement-এর পালা 😄'}`;if(/sale|সেল/.test(z))return `স্যার, confirmed delivered sales ${rm(d)}। Pending order আমি achievement-এ ধরিনি।`;if(/income|ইনকাম|আয়/.test(z))return `স্যার, Income screen-এ fixed income, commission, incentives এবং penalty মিলিয়ে net amount দেখানো আছে।`;if(/outlet|focus|ফোকাস|route|রুট/.test(z)){let os=outlets(id),done=new Set(db.sales.filter(x=>x.sr===id&&x.status==='Delivered').map(x=>x.outletCode)),zero=os.filter(o=>!done.has(o.code));if(!os.length)return 'স্যার, এই SR-এর outlet route এখনো assign করা নেই—আমি বানিয়ে outlet বলব না।';return `স্যার, ${os.length} assigned outlet-এর মধ্যে ${zero.length}টিতে confirmed delivery নেই। আগে ${zero.slice(0,3).map(x=>x.name).join(', ')} ফোকাস করতে পারেন।`}if(/pending|ডেলিভারি/.test(z)){let p=db.sales.filter(x=>x.sr===id&&x.status!=='Delivered').length;return `স্যার, ${p}টি order Pending Delivery আছে। Confirm না হওয়া পর্যন্ত dashboard sales-এ যাবে না।`}let kb=aiKbAnswer(s);if(kb)return kb;let salesScope=/sales|sale|buyer|order|outlet|target|sku|stock|display|marketing|market|merchand|price|promotion|cpo|route|income|incentive|report|sop|visit|delivery|proposal|app|fieldforce|সেল|বায়ার|বায়ার|অর্ডার|আউটলেট|টার্গেট|স্টক|ডিসপ্লে|মার্কেট|প্রমোশন|রুট|ইনকাম|ইনসেনটিভ|রিপোর্ট|ভিজিট|ডেলিভারি|প্রপোজাল|অ্যাপ/.test(z);if(!salesScope)return 'স্যার, AYON AI-কে Sales, company SOP এবং FieldForce Hub-এর কাজের জন্য রাখা হয়েছে। এই প্রশ্নটা ওই scope-এর বাইরে।';return ffhAiPersonality(ffhAiFallback(s),s)}
function askAI(){let inp=q('#ask'),s=inp.value.trim();if(!s)return;let c=q('#chat');c.innerHTML+=`<div class="bubble me">${esc(s)}</div>`;let a=aiAnswer(s);c.innerHTML+=`<div class="bubble bot">${a}</div>`;inp.value='';c.scrollTop=c.scrollHeight}
function setupMic(){let B=q('#mic');let SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){B.onclick=()=>alert('Voice input is not supported by this browser.');return}let r=new SR();r.lang=lang==='bn'?'bn-BD':'en-US';r.onstart=()=>B.classList.add('listening');r.onend=()=>B.classList.remove('listening');r.onresult=e=>{q('#ask').value=e.results[0][0].transcript;askAI()};B.onclick=()=>r.start()}
function globalSearch(s){s=s.trim().toLowerCase();if(!s)return;let m=mods.find(x=>x[2].toLowerCase().includes(s)||x[1].includes(s));if(m)return go(m[1]);let id=currentSr()||user.id,o=outlets(id).find(x=>x.name.toLowerCase().includes(s)||x.code.includes(s));if(o){alert(`${o.name}\n${o.code}\n${o.category}`);return}let p=catalogueProducts().find(x=>x.toLowerCase().includes(s));if(p)alert(p);else alert('No matching module, outlet or SKU found.')}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
try{if('serviceWorker' in navigator){navigator.serviceWorker.register('sw.js').catch(()=>{})}}catch(_){}
try{initNotifications()}catch(_){}

function ffhRestoreLastPage(){
 let p=localStorage.getItem('ffh_last_page')||'home';
 if(p==='catalogue')return catalogue();
 if(p.startsWith('catalogueCategory:'))return catalogueCategory(p.slice('catalogueCategory:'.length));
 if(p==='proposals')return proposals();
 let fn=({dashboard,zero,sales,income,incentive,cpo,route,tasks,reports,control,ai,notifications,profile})[p];
 if(fn){currentPage=p;return fn(true)}
 return home(true)
}

/* ===== V66 NATIVE MOBILE BACK / PAGE HISTORY ===== */
let ffhHistoryRendering=false, ffhExitPromptOpen=false;
function ffhHistoryPage(){return currentPage||'home'}
function ffhSyncBrowserHistory(){
 if(!user||currentPage==='login'||ffhHistoryRendering)return;
 let p=ffhHistoryPage(),cur=history.state?.ffhPage;
 if(!cur){history.replaceState({ffhPage:p},'',location.href);return}
 if(cur!==p)history.pushState({ffhPage:p},'',location.href);
}
function ffhExitPrompt(){
 if(ffhExitPromptOpen)return;ffhExitPromptOpen=true;
 let o=document.createElement('div');o.className='globalSearchOverlay ffExitOverlay';
 o.innerHTML=`<div class="globalSearchBox ffPremiumModal ffExitModal"><div class="cardTitle">Exit FieldForce Hub?</div><div class="notice">Are you confirm to exit?</div><div class="ffExitActions"><button type="button" class="secondary" id="ffExitCancel">NO</button><button type="button" class="primary" id="ffExitYes">EXIT</button></div></div>`;
 document.body.appendChild(o);
 const close=()=>{ffhExitPromptOpen=false;o.remove()};
 o.querySelector('#ffExitCancel').onclick=close;
 o.querySelector('#ffExitYes').onclick=()=>{close();window.__FFH_ALLOW_EXIT__=true;history.go(-2)};
 o.onclick=e=>{if(e.target===o)close()};
}
function ffhRenderHistoryPage(p){
 ffhHistoryRendering=true;
 try{
  if(p==='home')return home(true);
  if(p==='catalogue')return catalogue();
  if(p.startsWith('catalogueCategory:'))return catalogueCategory(p.slice('catalogueCategory:'.length));
  if(p==='proposals')return proposals();
  if(p.startsWith('control:')){currentPage=p;return controlPage(p.split(':')[1])}
  if(p.startsWith('report:')){currentPage=p;return reports()}
  let fn=({dashboard,zero,sales,income,incentive,cpo,route,tasks,reports,control,ai,notifications,profile})[p];
  if(fn){currentPage=p;return fn(true)}
  return home(true);
 }finally{setTimeout(()=>{ffhHistoryRendering=false},0)}
}
window.addEventListener('popstate',e=>{
 if(window.__FFH_ALLOW_EXIT__)return;
 if(!user)return;
 if(currentPage==='home'){
  history.pushState({ffhPage:'home'},'',location.href);
  ffhExitPrompt();return;
 }
 let p=e.state?.ffhPage||'home';
 let idx=navStack.length?navStack.length-1:-1;if(idx>=0)navStack.pop();
 ffhRenderHistoryPage(p);
});

(function(){let st=document.createElement('style');st.id='ffh-v66-nav-style';st.textContent=`.ffNoScreenBack{padding-left:0!important}.ffNoScreenBack h1{margin-left:0!important}.ffExitModal{max-width:360px!important}.ffExitActions{display:grid!important;grid-template-columns:1fr 1fr!important;gap:10px!important;margin-top:16px!important}.ffExitActions button{min-height:48px!important;border-radius:14px!important;font-weight:900!important}`;document.head.appendChild(st)})();

window.addEventListener('beforeunload',()=>{if(user&&currentPage&&currentPage!=='login')localStorage.setItem('ffh_last_page',currentPage)});
(async()=>{try{const {data,error}=await FFH_SUPABASE.auth.getSession();if(error||!data?.session?.user){login();return}const profile=await ffhProfile(data.session.user.id);if(!profile||profile.active===false){await FFH_SUPABASE.auth.signOut();localStorage.removeItem('ffh_session');login();return}let old=null;try{old=JSON.parse(localStorage.getItem('ffh_session')||'null')}catch(_){}let mode=old?.mode==='MANAGER'&&profile.can_manage?'MANAGER':'SR';if(mode==='SR'&&!profile.can_sell){await FFH_SUPABASE.auth.signOut();localStorage.removeItem('ffh_session');login();return}user=ffhUser(profile,mode);view=mode==='MANAGER'?'ALL':user.id;localStorage.setItem('ffh_session',JSON.stringify(user));await Promise.allSettled([ffhLoadCpoShared(),ffhLoadAiShared(),ffhRefreshOwnProfile(),ffhLoadTasksCloud()]);ffhStartCloudNotices();ffhRestoreLastPage()}catch(e){console.error('Supabase session restore failed:',e);login()}})();
/* ===== V72 CPO + AI KB SHARED CLOUD (CATALOGUE UNTOUCHED) ===== */
async function ffhSharedGet(key){if(!window.FFH_SUPABASE)return null;let {data,error}=await FFH_SUPABASE.from('ffh_shared_content').select('payload').eq('content_key',key).maybeSingle();if(error){console.warn('Shared load '+key,error.message);throw new Error('Cloud '+key+': '+error.message)}return data?.payload??null}
async function ffhSharedPut(key,payload){if(!window.FFH_SUPABASE)throw new Error('Supabase is not connected');if(user?.mode!=='MANAGER')throw new Error('Manager access required to publish');let {error}=await FFH_SUPABASE.from('ffh_shared_content').upsert({content_key:key,payload,updated_at:new Date().toISOString(),updated_by:user?.id||''},{onConflict:'content_key'});if(error)throw error;if(key==='notification_cloud'&&payload?.settings){let s=payload.settings,{error:pe}=await FFH_SUPABASE.from('ffh_notification_preferences').upsert({id:1,morning_time:s.notifyMorning||'08:30',evening_time:s.notifyEvening||'20:25',updated_by:user.id,updated_at:new Date().toISOString()},{onConflict:'id'});if(pe)throw pe}if(key==='notification_cloud'&&Array.isArray(payload?.messages)&&payload.messages.length){const n=payload.messages[payload.messages.length-1],fresh=Math.abs(Date.now()-new Date(n.snapshotAt||0).getTime())<15000,mark='ffh_push_queued_'+n.id;if(fresh&&!localStorage.getItem(mark)){await ffhQueuePush({to:n.to||'ALL',type:n.type||'manual',title:n.title||'FieldForce Hub',body:n.body||'',at:n.at||null});localStorage.setItem(mark,'1')}}}
async function ffhQueuePush({to='ALL',type='manual',title='FieldForce Hub',body,at=null}){if(!window.FFH_SUPABASE)throw new Error('Supabase is not connected');if(!user?.id)throw new Error('Login required');let when=at?new Date(at):new Date();if(Number.isNaN(when.getTime()))throw new Error('Invalid notification time');let {data,error}=await FFH_SUPABASE.from('ffh_notification_jobs').insert({recipient:String(to),type:String(type),title:String(title).slice(0,120),body:String(body||'').slice(0,1800),scheduled_at:when.toISOString(),status:'scheduled',created_by:user.id}).select('id,status,scheduled_at').single();if(error)throw error;return data}
async function ffhLoadTasksCloud(){if(!window.FFH_SUPABASE||!user)return false;let {data,error}=await FFH_SUPABASE.from('ffh_tasks').select('*').order('created_at',{ascending:false}).limit(500);if(error){console.warn('Task cloud load:',error.message);return false}let cloud=(data||[]).map(x=>({id:x.id,title:x.title,description:x.description||'',to:x.assigned_to,by:x.given_by||'',byId:x.given_by_id||'',due:x.due_date||'',priority:x.priority||'Normal',status:String(x.status||'Open').toLowerCase()==='done'?'Done':'Open',created:x.created_date,doneAt:x.done_at||''}));let byId=new Map((db.tasks||[]).map(x=>[String(x.id),x]));cloud.forEach(x=>byId.set(String(x.id),{...(byId.get(String(x.id))||{}),...x}));db.tasks=[...byId.values()];save();return true}
async function ffhSaveTaskCloud(task){let row={id:task.id,title:task.title,description:task.description||'',assigned_to:task.to,given_by:task.by||user.name,given_by_id:task.byId||user.id,due_date:task.due||null,priority:task.priority||'Normal',status:task.status||'Open',created_date:task.created||today(),done_at:task.doneAt||null,updated_at:new Date().toISOString()};let {error}=await FFH_SUPABASE.from('ffh_tasks').upsert(row,{onConflict:'id'});if(error)throw error;return row}
async function ffhLoadCpoShared(){let p=await ffhSharedGet('cpo_campaigns');if(Array.isArray(p)){db.cpoCampaigns=p;localStorage.setItem(K,JSON.stringify(db));return true}return false}
async function ffhSaveCpoShared(){await ffhSharedPut('cpo_campaigns',db.cpoCampaigns||[])}
async function ffhLoadAiShared(){let p=await ffhSharedGet('ai_knowledge');if(p&&typeof p==='object'){db.kb={...(db.kb||{}),...p};try{localStorage.setItem(K,JSON.stringify(db))}catch(e){console.warn('Large KB cloud-only cache:',e.message)}return true}return false}
async function ffhSaveAiShared(){await ffhSharedPut('ai_knowledge',db.kb||{})}
/* Cross-device notification settings and manager announcements; foreground delivery.
   Background/closed-app push requires a separate authenticated push sender. */
let ffhNoticeTimer=null;
async function ffhCloudNoticeSync(){
 if(!user||!window.FFH_SUPABASE)return;
 try{
  const payload=await ffhSharedGet('notification_cloud');if(!payload||typeof payload!=='object')return;
  if(payload.settings&&typeof payload.settings==='object')db.settings={...db.settings,...payload.settings};
  const mine=String(user.id||'').toUpperCase();
  for(const n of (Array.isArray(payload.messages)?payload.messages:[])){
   if(!n||!n.id)continue;
   const to=String(n.to||'ALL').toUpperCase();if(isMgr()&&to!=='ALL'&&to!==mine)continue;if(!isMgr()&&to!=='ALL'&&to!==mine)continue;
   const at=n.at?new Date(n.at).getTime():0;if(at&&at>Date.now())continue;
   const seenKey='ffh_cloud_notice_'+mine+'_'+n.id;if(localStorage.getItem(seenKey))continue;
   const msg={id:String(n.id),title:String(n.title||'FieldForce Hub'),body:String(n.body||''),date:n.at||new Date().toISOString(),read:false};
   db.notifications=db.notifications||[];if(!db.notifications.some(x=>x.id===msg.id))db.notifications.unshift(msg);
   localStorage.setItem(seenKey,'1');try{save()}catch(e){console.warn('Notice local cache full',e)}
   notifyNow(msg.title,msg.body);
  }
  updateNotifyBadges();
 }catch(e){console.warn('Cloud notification refresh failed',e)}
}
function ffhBuildReportNotice(type,to){
 const ids=to==='ALL'?srIds():[to];const who=to==='ALL'?'All SR':(sr(to)?.name||to);
 const line=id=>{const os=outlets(id)||[],zero=zeroOutlets(id)||[];const d=delivered(id)||0,t=target(id)||0;return {os,zero,d,t,name:sr(id)?.name||id}};
 const rows=ids.map(id=>({id,...line(id)}));const own=rows.length===1?rows[0]:null;
 const total=(k)=>rows.reduce((a,x)=>a+(x[k]||0),0);
 const heading={zero:'Zero Sales Report',dashboard:'Dashboard Summary',income:'Income Reminder',cpo:'CPO / Promotion Update',incentive:'Incentive & Penalty',sales:'Sales & Target Report',tasks:'Pending Task Reminder',route:'Route & Outlet Coverage',custom:'Custom Reminder',manual:'FieldForce Hub'};
 let body='';switch(type){
 case 'zero':body=rows.map(x=>`${x.name}: ${x.zero.length} zero-sale / ${x.os.length} assigned outlets\n${x.zero.slice(0,20).map(o=>`• ${o.name} (${o.code||'no code'})`).join('\n')}${x.zero.length>20?'\n...plus '+(x.zero.length-20)+' more':''}`).join('\n\n');break;
 case 'dashboard':case 'sales':body=rows.map(x=>`${x.name}: Delivered ${rm(x.d)} / Target ${rm(x.t)}; Shortfall ${rm(Math.max(0,x.t-x.d))}; Zero-sale outlets ${x.zero.length}`).join('\n');break;
 case 'route':body=rows.map(x=>`${x.name}: Assigned ${x.os.length}; Zero-sale ${x.zero.length}; Covered ${Math.max(0,x.os.length-x.zero.length)}`).join('\n');break;
 case 'tasks':body=ids.map(id=>{let a=(db.tasks||[]).filter(t=>(t.to==='ALL'||t.to===id)&&t.status!=='Done');return `${sr(id)?.name||id}: ${a.length} pending tasks${a.length?'\n'+a.slice(0,12).map(t=>'• '+t.title+(t.due?' (Due '+t.due+')':'')).join('\n'):''}`}).join('\n\n');break;
 case 'cpo':body=ids.map(id=>{let a=(db.cpoCampaigns||[]).filter(c=>!c.sr||c.sr==='ALL'||c.sr===id);return `${sr(id)?.name||id}: ${a.length} assigned CPO / Promotion campaigns${a.length?'\n'+a.slice(0,8).map(c=>'• '+(c.title||c.product||c.type||'Campaign')).join('\n'):''}`}).join('\n\n');break;
 case 'incentive':body=ids.map(id=>{let a=(db.incentives||[]).filter(c=>!c.sr||c.sr==='ALL'||c.sr===id);return `${sr(id)?.name||id}: ${a.length} incentive entries${a.length?'\n'+a.slice(0,8).map(c=>'• '+(c.name||'Incentive')).join('\n'):''}`}).join('\n\n');break;
 case 'income':body=`${who}: Please review your Income screen for the latest personal income, incentive and penalty details. Personal financial amounts are not broadcast.`;break;
 case 'custom':body='';break;
 default:body='';
 }
 return{title:heading[type]||'FieldForce Hub',body:body||((type==='manual'||type==='custom')?'':'No matching records in this Manager device. Verify cloud data before sending.')};
}
function ffhStartCloudNotices(){if(ffhNoticeTimer)clearInterval(ffhNoticeTimer);ffhCloudNoticeSync();ffhNoticeTimer=setInterval(ffhCloudNoticeSync,60000)}

/* Cloud-first task and personal-reminder bridge. Capture prevents the legacy
   local-only handlers from running, while retaining the existing screen/UI. */
document.addEventListener('submit',async function(e){
 const form=e.target;if(!form||!['taskForm','noteForm'].includes(form.id))return;
 e.preventDefault();e.stopImmediatePropagation();const btn=form.querySelector('button');if(btn)btn.disabled=true;
 try{
  if(form.id==='taskForm'){
   const x={...Object.fromEntries(new FormData(form)),id:'T'+Date.now(),by:user.name,byId:user.id,created:today(),status:'Open'};
   await ffhSaveTaskCloud(x);
   await ffhQueuePush({to:x.to,type:'task',title:'New Manager Task',body:x.title+(x.due?' — Due '+x.due:'')});
   db.tasks.push(x);save();tasks();
  }else{
   const n=Object.fromEntries(new FormData(form));
   if(n.remind)await ffhQueuePush({to:user.id,type:'personal',title:'FieldForce Reminder',body:n.text,at:n.remind});
   db.notes.push({...n,id:'N'+Date.now(),owner:user.id});save();scheduleNoteReminder(n);tasks();
  }
 }catch(err){alert((form.id==='taskForm'?'Task was not published: ':'Reminder was not scheduled: ')+(err?.message||err));if(btn)btn.disabled=false}
},true);
document.addEventListener('click',async function(e){
 const b=e.target?.closest?.('.taskDone');if(!b)return;e.preventDefault();e.stopImmediatePropagation();
 const x=db.tasks.find(t=>String(t.id)===String(b.dataset.id));if(!x)return;const old={status:x.status,doneAt:x.doneAt};
 x.status=x.status==='Done'?'Open':'Done';x.doneAt=x.status==='Done'?new Date().toISOString():'';b.disabled=true;
 try{await ffhSaveTaskCloud(x);save();tasks()}catch(err){Object.assign(x,old);b.disabled=false;alert('Cloud task update failed: '+(err?.message||err))}
},true);

async function ffhRefreshOwnProfile(){if(!window.FFH_SUPABASE||!user?.id)return;let {data,error}=await FFH_SUPABASE.from('ffh_profiles').select('full_name,photo_url').eq('staff_id',user.id).maybeSingle();if(!error&&data){if(data.full_name)user.name=data.full_name;if(data.photo_url)user.photo=data.photo_url;let u=db.users.find(x=>x.id===user.id);if(u){if(data.full_name)u.name=data.full_name;if(data.photo_url)u.photo=data.photo_url}localStorage.setItem('ffh_session',JSON.stringify(user));localStorage.setItem(K,JSON.stringify(db))}}

