const FFH_PREMIUM_CATALOGUE_STYLE=document.createElement('style');FFH_PREMIUM_CATALOGUE_STYLE.textContent=`
.ffPremiumDownloadFooter{margin:35px 0 12px;padding:23px 14px;background:linear-gradient(135deg,#111d23,#2a1a13);border:1px solid #e77a28;border-radius:20px;text-align:center;color:white}.ffPremiumDownloadFooter h3{color:#ff9a46;margin:0 0 8px}.ffPremiumDownloadFooter p{color:#b4b8bd;font-size:12px}.ffPremiumDownloadFooter .ffCatDownloads{justify-content:center}.ffPremiumDownloadFooter button{flex:1;max-width:230px;box-shadow:0 4px 17px #ec781433}.ffCatFilters select,.ffFilterPanel select{min-width:105px;flex:1;background:#111c22;color:#fff;border:1px solid #a95a26;border-radius:12px;padding:13px 8px}.ffPremiumSku{overflow:hidden}.ffPremiumSku .ffProductVisual{height:clamp(250px,52vw,400px)!important;display:flex;align-items:center;justify-content:center;background:#fff;padding:9px}.ffPremiumSku .ffProductVisual img{height:100%!important;width:100%!important;object-fit:contain!important;object-position:center!important}.ffPremiumSku .ffProductName{padding:13px 14px 8px!important;min-height:54px}.ffSkuFour{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px;padding:8px}.ffSkuBarcodes{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:5px;padding:0 8px 10px}.ffSkuChip{min-width:0;display:flex;flex-direction:column;gap:5px;padding:10px 5px;background:linear-gradient(155deg,#27302e,#11171a);border:1px solid #c67938;border-radius:12px;overflow-wrap:anywhere}.ffSkuChip small{font-size:9px;color:#fca664;font-weight:800;letter-spacing:.1px}.ffSkuChip strong{font-size:clamp(9px,2.6vw,14px);color:#fff;overflow-wrap:anywhere}.ffSkuExtra{padding:6px 12px;font-size:10px}.ffPremiumSku .ffViewDetails{margin:8px;width:calc(100% - 16px);border-radius:16px!important;min-height:52px}.ffSkuFullModal{position:fixed;inset:0;z-index:999999;background:#081015;overflow-y:auto;overscroll-behavior:contain;color:#fff}.ffSkuModalHead{position:sticky;top:0;z-index:2;background:#0b1419;border-bottom:1px solid #e67b31;padding:12px;display:flex;align-items:center;gap:20px;color:#ff9e4d;font-weight:900;font-size:12px}.ffSkuClose{font-size:34px;line-height:1;border:1px solid #f18a37;border-radius:50%;width:48px;height:48px;color:#ffab68;background:#172027}.ffSkuModalBody{max-width:900px;margin:auto;padding:15px 15px 90px}.ffSkuModalHero{display:grid;grid-template-columns:minmax(0,150px) 1fr;gap:15px;align-items:center;background:linear-gradient(120deg,#17252c,#2a1b14);border:1px solid #f18a37;border-radius:20px;padding:15px}.ffSkuModalHero img{width:100%;max-height:210px;object-fit:contain;background:#fff;border-radius:14px}.ffSkuModalHero h1{font-size:clamp(18px,5vw,28px);line-height:1.25;margin:8px 0;color:#fff}.ffSkuModalHero small{color:#ffa259}.ffSkuModalHero p{font-size:12px;line-height:1.6}.ffSkuDetailGrid{display:grid;grid-template-columns:1fr;gap:13px;margin-top:18px}.ffSkuDetailPanel{position:relative;background:linear-gradient(150deg,#17242a,#0d151a);border:1px solid #bc6b2d;border-radius:17px;padding:18px;overflow-wrap:anywhere}.ffSkuPanelNumber{font-size:11px;color:#ffae6c;font-weight:900}.ffSkuDetailPanel h2{font-size:17px;color:#ff9950;margin:8px 0 12px}.ffSkuDetailPanel p{font-size:15px;line-height:1.8;white-space:normal}.ffSkuModalEdit{display:block;margin:22px auto;border:1px solid #ed7c2d;background:#291b14;color:#ffa764;border-radius:12px;padding:16px}.ffCategoryBanner{max-height:250px;overflow:hidden}.ffCategoryBanner img{object-fit:cover}@media(min-width:700px){.ffSkuDetailGrid{grid-template-columns:repeat(2,minmax(0,1fr))}.ffSkuModalHero{grid-template-columns:220px 1fr}}`;
document.head.appendChild(FFH_PREMIUM_CATALOGUE_STYLE);

(function(){const style=document.createElement('style');style.id='ffh-premium-card-final';style.textContent='\n /* Catalogue premium v2: balanced four chips, uncluttered identifier rows */\n .ffPremiumSku{background:linear-gradient(145deg,#101c24 0%,#0b1219 53%,#20140f 100%)!important;border:1px solid #e78b40!important;border-radius:24px!important;box-shadow:0 12px 36px #0009,0 0 0 1px #ffa85b19,inset 0 1px 0 #fff2!important}\n .ffPremiumSku .ffProductVisual{height:clamp(245px,59vw,430px)!important;aspect-ratio:auto!important;background:radial-gradient(ellipse at 50% 52%,#fff 35%,#f6f8fb 100%)!important;padding:5px!important;overflow:hidden!important}\n .ffPremiumSku .ffProductVisual .productImg{height:100%!important;width:100%!important;object-fit:contain!important;object-position:center!important;cursor:zoom-in!important}\n .ffPremiumSku .ffProductName{display:block!important;min-height:67px!important;text-align:center!important;font-size:clamp(14px,3.5vw,19px)!important;line-height:1.28!important;padding:16px 9px 8px!important}\n .ffPremiumSku .ffSkuFour{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:9px!important;padding:8px 10px 14px!important}\n .ffPremiumSku .ffSkuFour .ffSkuChip{min-height:92px!important;padding:11px 5px!important;align-items:center!important;justify-content:center!important;text-align:center!important;gap:9px!important;border:1px solid #f2a359!important;border-radius:18px!important;background:linear-gradient(150deg,#3b322c 0%,#1b2428 49%,#10191e 100%)!important;box-shadow:inset 0 1px 0 #fff4,inset 0 -8px 15px #0003,0 4px 15px #0005,0 0 11px #ef87321a!important}\n .ffPremiumSku .ffSkuFour .ffSkuChip small{font-size:clamp(9px,2.35vw,12px)!important;line-height:1.3!important;letter-spacing:.15px!important;color:#ffb77c!important;overflow-wrap:normal!important}\n .ffPremiumSku .ffSkuFour .ffSkuChip strong{font-size:clamp(13px,3.5vw,20px)!important;line-height:1.25!important;color:#fff!important;overflow-wrap:break-word!important}\n .ffSkuIdentity{margin:1px 11px 12px;border-top:1px solid #f8a75a60;border-bottom:1px solid #f8a75a60;padding:6px 0}\n .ffSkuIdentity>div{display:flex;align-items:baseline;justify-content:space-between;gap:8px;padding:9px 2px;border-bottom:1px solid #ffffff16}\n .ffSkuIdentity>div:last-child{border-bottom:0}\n .ffSkuIdentity span{flex:0 1 49%;color:#ffad70;font-size:clamp(9px,2.15vw,12px);font-weight:850;line-height:1.3;letter-spacing:0;overflow-wrap:normal}\n .ffSkuIdentity strong{flex:1 1 51%;min-width:0;color:#fff;text-align:right;font-size:clamp(10px,2.55vw,14px);font-weight:800;line-height:1.35;overflow-wrap:anywhere}\n .ffPremiumSku .ffViewDetails{width:calc(100% - 22px)!important;margin:7px 11px 13px!important;min-height:59px!important;background:linear-gradient(130deg,#392419,#1b1716 52%,#4b2818)!important;border:1px solid #ffa45c!important;box-shadow:inset 0 1px 0 #fff4,0 5px 18px #ff792328!important;color:#ffb279!important;letter-spacing:.35px!important}\n @media(max-width:390px){.ffPremiumSku .ffSkuFour .ffSkuChip{min-height:82px!important}.ffSkuIdentity span{font-size:9px!important}}\n';document.head.appendChild(style)})();

(function(){const st=document.createElement("style");st.id="ffh-compact-card-override";st.textContent='\n/* compact card override: preserve photo height and photo zoom */\n.ffPremiumSku .ffProductName{min-height:0!important;padding:9px 5px 4px!important;margin:0!important;font-size:clamp(13px,3.25vw,17px)!important;line-height:1.18!important}\n.ffPremiumSku .ffSkuFour{gap:5px!important;padding:5px 8px 7px!important}\n.ffPremiumSku .ffSkuFour .ffSkuChip{min-height:49px!important;height:auto!important;gap:2px!important;padding:5px 4px!important;border-radius:7px!important;box-shadow:inset 0 1px 0 #ffffff3d,0 2px 7px #0005!important}\n.ffPremiumSku .ffSkuFour .ffSkuChip small{font-size:clamp(8px,2.05vw,10px)!important;line-height:1.06!important;letter-spacing:0!important;margin:0!important}\n.ffPremiumSku .ffSkuFour .ffSkuChip strong{font-size:clamp(11px,3vw,15px)!important;line-height:1.13!important;margin:0!important}\n.ffPremiumSku .ffSkuIdentity{margin:0 9px 4px!important;padding:1px 0!important;border-top:1px solid #e9a25a5c!important;border-bottom:0!important}\n.ffPremiumSku .ffSkuIdentity>div{display:grid!important;grid-template-columns:minmax(0,44%) minmax(0,56%)!important;align-items:center!important;gap:3px!important;padding:5px 1px!important}\n.ffPremiumSku .ffSkuIdentity span{font-size:clamp(8px,1.95vw,10px)!important;line-height:1.15!important;word-break:normal!important;overflow-wrap:normal!important}\n.ffPremiumSku .ffSkuIdentity strong{font-size:clamp(9px,2.25vw,12px)!important;line-height:1.15!important;white-space:nowrap!important;overflow-wrap:normal!important;letter-spacing:-.3px!important}\n.ffPremiumSku .ffViewDetails{min-height:37px!important;padding:6px 5px!important;margin:4px 9px 9px!important;width:calc(100% - 18px)!important;border-radius:8px!important;font-size:clamp(10px,2.6vw,13px)!important;line-height:1.12!important;letter-spacing:0!important}\n';document.head.appendChild(st)})();

(function(){let st=document.createElement('style');st.id='ffh-midnight-gold-photo';st.textContent='\n/* Catalogue Midnight Gold photo gallery */\n.ffPremiumSku .ffProductVisual{\n height:clamp(245px,59vw,430px)!important;\n background:radial-gradient(ellipse at 50% 44%,#263440 0%,#101b23 55%,#050b10 100%)!important;\n border:2px solid #d6a25b!important;\n border-radius:18px!important;\n box-shadow:inset 0 0 0 3px #0d1820,inset 0 0 28px #e5a65e18,0 0 17px #e5a65e28!important;\n padding:9px!important;\n}\n.ffPremiumSku .ffProductVisual .productImg{\n height:100%!important;width:100%!important;object-fit:contain!important;\n object-position:center!important;background:transparent!important;\n filter:drop-shadow(0 9px 12px #0009)!important;\n}\n.ffPremiumSku .ffProductVisual .productPlaceholder{\n color:#efb66d!important;background:transparent!important;font-size:13px!important;\n border:1px dashed #c7955b66!important;border-radius:12px!important;\n}\n.ffPremiumSku .ffProductName{\n color:#f7f9fa!important;text-align:center!important;\n font-weight:900!important;line-height:1.35!important;\n text-wrap:balance!important;\n}\n.ffPremiumSku .ffProductName::first-line{color:#ffb56e!important}\n.ffPremiumSku .ffSkuFour .ffSkuChip:active,\n.ffPremiumSku .ffViewDetails:active,.ffPremiumSku .skuMenuBtn:active{\n transform:translateY(1px) scale(.985)!important;\n box-shadow:inset 0 1px 7px #0008,0 0 0 2px #ffad6388!important;\n}\n.imageLightbox{background:rgba(3,9,14,.97)!important}\n.imageLightbox img{max-width:95vw!important;max-height:85vh!important;object-fit:contain!important;filter:drop-shadow(0 0 18px #d6a25b33)!important}\n';document.head.appendChild(st)})();

